namespace UniversalPOS.Domain.Entities;
public class Supplier { public int Id {get; private set;} public string Name {get; private set;}=string.Empty; public string? Phone {get; private set;} public string? TaxNumber {get; private set;} public bool IsActive {get; private set;}=true; private Supplier(){} public Supplier(string name,string? phone=null,string? taxNumber=null){if(string.IsNullOrWhiteSpace(name))throw new ArgumentException("Supplier name is required.");Name=name.Trim();Phone=phone?.Trim();TaxNumber=taxNumber?.Trim();} public void UpdateContact(string? phone,string? taxNumber){Phone=phone?.Trim();TaxNumber=taxNumber?.Trim();} public void Deactivate()=>IsActive=false; }
